import itertools
import numpy as np
from scipy.optimize import minimize

def solve_for_set(s):
    min_t = float('inf')
    for subset in itertools.combinations(s, 4):
        for p in itertools.permutations(subset):
            e, f, g, h = p
            val = abs(e * f - g * h) / (f * h)
            if val < min_t:
                min_t = val
    return min_t

def objective(x):
    x = sorted(x)
    return -solve_for_set(x)

# Try different starting points
best_t = 0
for _ in range(10):
    start_x = sorted(np.random.uniform(1, 10, 5))
    res = minimize(objective, start_x, bounds=[(1, 10), (1, 10), (1, 10), (1, 10), (1, 10)])
    if -res.fun > best_t:
        best_t = -res.fun
        print(f"New best_t: {best_t} for {res.x}")

print(f"Final best_t: {best_t}")

